// Declarative CTA tracking via data-ph-capture attributes
// Include via: <script src="/tracking.js" defer></script>

document.addEventListener('DOMContentLoaded', function() {
  if (!window.posthog) return;

  document.querySelectorAll('[data-ph-capture]').forEach(function(el) {
    el.addEventListener('click', function() {
      posthog.capture(el.dataset.phCapture, {
        cta_text: el.textContent.trim(),
        page: window.location.pathname,
        location: el.dataset.phLocation || 'unknown'
      });
    });
  });
});
